ac1.command:
set -u
test -f README.md || { echo "ac1 RED: README.md missing - run the fence from the checkout root"; exit 1; }
T=$(tr -d '\r' < README.md)
O=$(printf "%s\n" "$T" | sed -n '/^## Online demo/,/^## /p')
[ -n "$O" ] || { echo "ac1 RED: no ## Online demo section - the section is rewritten in place, never removed"; exit 1; }
printf "%s\n" "$O" | grep -qE "https://expense-tracker-dashboard-1qtu[.]onrender[.]com" || { echo "ac1 RED: ## Online demo does not state the real live -1qtu address - the whole point of this card is that the reader gets the measured URL, not a placeholder"; exit 1; }
printf "%s\n" "$O" | grep -qiE "no seeded demo account" || { echo "ac1 RED: ## Online demo does not state that the hosted app has NO seeded demo account - claiming a hosted demo login is a FAIL, the factpack records no such account"; exit 1; }
printf "%s\n" "$O" | grep -qF "npm run seed:demo" || { echo "ac1 RED: ## Online demo lost the local seeded demo path - the local demo stays the documented demo route"; exit 1; }
printf "%s\n" "$O" | grep -qF "demo@example.com" || { echo "ac1 RED: ## Online demo lost the fixed local demo account - tests[237] seeds exactly that account and the section names it"; exit 1; }
HOSTED=$(printf "%s\n" "$O" | sed -n '/expense-tracker-dashboard-1qtu[.]onrender[.]com/,$p')
if printf "%s\n" "$HOSTED" | grep -qE "demo@example[.]com|demo-password"; then
  echo "ac1 RED: the hosted-address region names demo credentials - the fixed demo account exists only in a LOCAL database after npm run seed:demo and must never be implied on the live host"; exit 1
fi
SM=0
printf "%s\n" "$O" | grep -qiE "no seeded demo account" || SM=$((SM+1))
printf "%s\n" "$HOSTED" | grep -qE "demo@example[.]com|demo-password" && SM=$((SM+1))
SYN=$(printf '%s\n' '## Online demo' '' 'Sign in on https://expense-tracker-dashboard-1qtu.onrender.com with the hosted demo account demo@example.com / demo-password-123 - every visitor shares it.')
SYNH=$(printf "%s\n" "$SYN" | sed -n '/expense-tracker-dashboard-1qtu[.]onrender[.]com/,$p')
printf "%s\n" "$SYN" | grep -qiE "no seeded demo account" || SM=$((SM+1))
printf "%s\n" "$SYNH" | grep -qE "demo@example[.]com|demo-password" && SM=$((SM+1))
[ "$SM" -eq 2 ] || { echo "ac1 RED: NEGATIVE CONTROL FAILED - a section claiming a hosted shared demo login was refused by $SM of 2 honesty legs (want 2), so the legs above are vacuous"; exit 1; }
echo "ac1 GREEN: ## Online demo states the real -1qtu address, states the hosted app has NO seeded demo account, keeps the local seed:demo path and the fixed local account, names no credential on the hosted side, and the negative control (a hosted-login claim) is refused by 2 of 2 honesty legs"

ac2.command:
set -u
test -f README.md || { echo "ac2 RED: README.md missing - run the fence from the checkout root"; exit 1; }
T=$(tr -d '\r' < README.md)
printf "%s\n" "$T" | grep -qE "^## Deployment on Render[[:space:]]*$" || { echo "ac2 RED: the ## Deployment on Render heading is gone - tests[135] and tests[201] grep it and it is load-bearing"; exit 1; }
RS=$(printf "%s\n" "$T" | sed -n '/^## Deployment on Render/,$ p')
for H in "^### Why Render[[:space:]]*$" "^### First deployment[[:space:]]*$" "^### Free tier[[:space:]]*$" "^### UptimeRobot[[:space:]]*$"; do
  printf "%s\n" "$RS" | grep -qE "$H" || { echo "ac2 RED: the Render section lost the carried subheading $H - the tests[135] heading set survives the live-state rewrite verbatim"; exit 1; }
done
RX=REQ-
MISS=""
for tok in Blueprint "cold start" "10 min" "${RX}CICD-030" "${RX}CICD-036" "${RX}CICD-040" "${RX}CICD-041" "${RX}CICD-042" "${RX}CICD-043" "${RX}TECH-061"; do
  printf "%s\n" "$RS" | grep -qF "$tok" || MISS="$MISS $tok"
done
[ -z "${MISS// /}" ] || { echo "ac2 RED: the Render section lost the carried tests[135] token set:$MISS - prose is reworded, every token stays"; exit 1; }
printf "%s\n" "$RS" | grep -qF "render.yaml" || { echo "ac2 RED: the Render section never names render.yaml - the blueprint is the deployment-as-code deliverable"; exit 1; }
printf "%s\n" "$RS" | grep -qiE "RENDER_DEPLOY_HOOK" || { echo "ac2 RED: the Render section lost the deploy-hook secret step - residual #61 lives there"; exit 1; }
printf "%s\n" "$RS" | grep -qE "/api/v1/health" || { echo "ac2 RED: the Render section lost the health-check verification step"; exit 1; }
printf "%s\n" "$RS" | grep -qE "#61" || { echo "ac2 RED: the Render section no longer cites residual #61 - t95 closes it against this README, the citation must survive the live-state prose"; exit 1; }
printf "%s\n" "$RS" | grep -qE "https://expense-tracker-dashboard-1qtu[.]onrender[.]com" || { echo "ac2 RED: the Render section does not state the real live -1qtu address"; exit 1; }
printf "%s\n" "$RS" | grep -qE "api[.]render[.]com/deploy/" && { echo "ac2 RED: the Render section prints an api.render.com deploy-hook URL - tests[135] forbids it and this card fabricates nothing"; exit 1; }
printf "%s\n" "$RS" | grep -qEi "ghp_[A-Za-z0-9]{4,}|github_pat_|AKIA[0-9A-Z]{16}" && { echo "ac2 RED: the Render section looks like it pasted a credential"; exit 1; }
printf "%s\n" "$RS" | grep -oE "https?://[A-Za-z0-9._/-]+" | grep -vE "^https?://(localhost|127[.]0[.]0[.]1|expense-tracker-dashboard-1qtu[.]onrender[.]com)" >/dev/null && { echo "ac2 RED: the Render section names a URL that is neither localhost nor the real -1qtu host - the card states the measured address and fabricates no other host"; exit 1; }
SM=0
printf "%s\n" "$RS" | grep -qE "https://expense-tracker-dashboard-1qtu[.]onrender[.]com" || SM=$((SM+1))
SYN=$(printf '%s\n' '## Deployment on Render' '' '### Why Render' '' '### First deployment' '' '### Free tier' '' '### UptimeRobot' '' 'The blueprint render.yaml is imported and the service is live at https://expense-tracker.onrender.com - ping it from https://uptimerobot.example.com and trigger releases via https://api.render.com/deploy/srv-abc123.')
printf "%s\n" "$SYN" | grep -qE "https://expense-tracker-dashboard-1qtu[.]onrender[.]com" || SM=$((SM+1))
printf "%s\n" "$SYN" | grep -qE "#61" || SM=$((SM+1))
BADU=0
for u in $(printf "%s\n" "$SYN" | grep -oE "https?://[A-Za-z0-9._/-]+"); do
  case "$u" in http://localhost:*|https://localhost:*|http://127.0.0.1*|https://expense-tracker-dashboard-1qtu.onrender.com*) : ;; *) BADU=$((BADU+1)) ;; esac
done
[ "$BADU" -ge 1 ] && SM=$((SM+1))
printf "%s\n" "$SYN" | grep -qE "api[.]render[.]com/deploy/" && SM=$((SM+1))
[ "$SM" -eq 4 ] || { echo "ac2 RED: NEGATIVE CONTROL FAILED - a fabricated-host Render section was refused by $SM of 4 honesty legs (want 4), so the legs above are vacuous"; exit 1; }
echo "ac2 GREEN: ## Deployment on Render states the real -1qtu address, keeps the heading, the four subheadings, the ten tokens, render.yaml, RENDER_DEPLOY_HOOK, /api/v1/health and the #61 citation, prints no hook URL, no credential and no fabricated host, and the negative control is refused by 4 of 4 honesty legs"

ac3.command:
set -u
test -f README.md || { echo "ac3 RED: README.md missing - run the fence from the checkout root"; exit 1; }
test -f backend/scripts/docs_verification.py || { echo "ac3 RED: backend/scripts/docs_verification.py missing"; exit 1; }
command -v python3 >/dev/null || { echo "ac3 RED: python3 missing"; exit 1; }
command -v uv >/dev/null || command -v uv.exe >/dev/null || command -v cmd.exe >/dev/null || { echo "ac3 RED: no uv and no cmd.exe - the report cannot be regenerated"; exit 1; }
CL=$(tr -d '\r' < README.md | wc -l | tr -d " ")
CD=$(tr -d '\r' < README.md | sha256sum | awk '{print $1}')
PINL=$(tr -d '\r' < backend/scripts/docs_verification.py | sed -n 's/^README_LINES = \([0-9][0-9]*\)$/\1/p' | head -1)
PIND=$(tr -d '\r' < backend/scripts/docs_verification.py | sed -n 's/^README_DIGEST = "\([0-9a-f]*\)"$/\1/p' | head -1)
[ -n "$PINL" ] || { echo "ac3 RED: README_LINES constant not found in backend/scripts/docs_verification.py"; exit 1; }
[ -n "$PIND" ] || { echo "ac3 RED: README_DIGEST constant not found in backend/scripts/docs_verification.py"; exit 1; }
[ "$CL" = "$PINL" ] || { echo "ac3 RED: README_LINES is $PINL but README.md measures $CL lines - the builder must MEASURE the candidate README and write the measured number, never guess or carry the old 398"; exit 1; }
[ "$CD" = "$PIND" ] || { echo "ac3 RED: README_DIGEST is $PIND but README.md measures $CD - the digest pin must be measured from the builders OWN candidate bytes before commit"; exit 1; }
[ "$CD" != "ca9343a83784548c2a6a49f1a5f7196b0e14f3b0fe49d0e2e8f5f9d6896c5644" ] || { echo "ac3 RED: README_DIGEST still pins the old base README - t94 moves the triple-pin"; exit 1; }
[ "$PINL" != "398" ] || { echo "ac3 RED: README_LINES still pins the old base line count 398 - t94 moves the triple-pin"; exit 1; }
G="docs/criteria/docs_verification.md"
BAK=$(mktemp -d) || { echo "ac3 RED: mktemp failed"; exit 1; }
G1=$(mktemp) || { echo "ac3 RED: mktemp failed"; exit 1; }
G2=$(mktemp) || { echo "ac3 RED: mktemp failed"; exit 1; }
cp docs/criteria/*.md "$BAK"/
test -f "$G" || { echo "ac3 RED: $G missing"; exit 1; }
grep -qF "Generated by \`backend/scripts/docs_verification.py\`" "$G" || { echo "ac3 RED: $G lost its generated-by header - it is tool output, never hand-edit it to pass this gate"; exit 1; }
grep -qE "^\| 1 \| README under 500 lines \| REQ-DOC-010 \| executed \| README_MEASURE \|$" "$G" || { echo "ac3 RED: the README_MEASURE row of the evidence table is not executed - the pin move must keep the report honest"; exit 1; }
grep -qE "^CARRIED_REPORT PASS file=docs/criteria/agent_pack_verification.md rows=22$" "$G" || { echo "ac3 RED: the carried agent_pack report row broke - t94 must not touch docs/criteria/agent_pack_verification.md"; exit 1; }
grep -qE "LINK_CHECK PASS files=[0-9]+ links=[0-9]+ broken=0" "$G" || { echo "ac3 RED: the link check no longer passes with zero broken links - the rewritten README must keep every relative link real"; exit 1; }
grep -qE "README_MEASURE PASS lines=$CL digest=$CD" "$G" || { echo "ac3 RED: the shipped report does not record README_MEASURE PASS for these candidate bytes ($CL/$CD) - regenerate docs/criteria/docs_verification.md from the candidate tree with the pinned uv environment"; exit 1; }
R=$CD
if command -v uv >/dev/null; then
  (cd backend && PYTHONPATH=. uv run python scripts/docs_verification.py >/dev/null 2>&1) || true
  tr -d '\r' < "$G" > $G1
  (cd backend && PYTHONPATH=. uv run python scripts/docs_verification.py >/dev/null 2>&1) || true
  tr -d '\r' < "$G" > $G2
  cmp -s $G1 $G2 || { echo "ac3 RED: regenerating the report twice on the same tree produced different bytes - the report is not deterministic, fix the generator before shipping"; cp "$BAK"/*.md docs/criteria/; exit 1; }
  grep -qE "README_MEASURE PASS lines=$CL digest=$CD" $G1 || { echo "ac3 RED: regenerating the report from THIS tree does not yield README_MEASURE PASS for the shipped pins - the shipped report does not match these candidate bytes"; cp "$BAK"/*.md docs/criteria/; exit 1; }
  grep -qE "LINK_CHECK PASS files=[0-9]+ links=[0-9]+ broken=0" $G1 || { echo "ac3 RED: regenerated link check is not PASS broken=0"; cp "$BAK"/*.md docs/criteria/; exit 1; }
  grep -qE "^CARRIED_REPORT PASS file=docs/criteria/agent_pack_verification.md rows=22$" $G1 || { echo "ac3 RED: regenerated carried agent_pack row broke"; cp "$BAK"/*.md docs/criteria/; exit 1; }
  cp "$BAK"/*.md docs/criteria/
  rm -f "$G1" "$G2"
  R=$(sed -n 's/^.*LINK_CHECK PASS files=\([0-9]*\) links=\([0-9]*\) broken=0.*$/\1 \2/p' $G1 | head -1)
fi
echo "ac3 GREEN: README triple-pin equals the candidate bytes (lines=$CL digest=$CD), the old base digest and line count are gone, the shipped report records README_MEASURE PASS for exactly these bytes, the link check passes broken=0 (files/links=$R), the carried agent_pack row survives, and regeneration is deterministic"

ac4.command:
set -u
test -f README.md || { echo "ac4 RED: README.md missing - run the fence from the checkout root"; exit 1; }
RAW=$(od -An -tx1 README.md | tr -d ' \n')
NL=$(python3 -c "import sys;b=open('README.md','rb').read();print(b.count(b'\n'))")
CRLF=$(python3 -c "import sys;b=open('README.md','rb').read();print(b.count(b'\r\n'))")
[ "$NL" = "$CRLF" ] || { echo "ac4 RED: $NL newlines but $CRLF CRLF pairs - README.md must stay all-CRLF like its base bytes"; exit 1; }
python3 -c "import sys;b=open('README.md','rb').read();sys.exit(0 if all(x<128 for x in b) else 1)" || { echo "ac4 RED: README.md carries non-ASCII bytes - the base file is pure ASCII and the merge diff filter treats a byte flip as a rewrite"; exit 1; }
T=$(tr -d '\r' < README.md)
CL=$(printf "%s\n" "$T" | wc -l | tr -d " ")
[ "$CL" -ge 340 ] && [ "$CL" -le 400 ] || { echo "ac4 RED: README.md measures $CL lines, outside the 340..400 envelope that holds every shipped README state - a structural rewrite is out of t94 scope"; exit 1; }
H2=$(printf "%s\n" "$T" | grep -cE "^## [^#]")
[ "$H2" = "17" ] || { echo "ac4 RED: README.md now carries $H2 level-2 headings, not the 17 of the base structure - t94 edits two sections in place and adds no heading"; exit 1; }
REQS=$(printf "%s\n" "$T" | grep -oE "REQ-[A-Z]+-[0-9]+" | sort -u | sha256sum | awk "{print \$1}")
[ "$REQS" = "01f3611817b98bd95baa2b709ba8c5e9f32be274d337a5fca8541deeb5413794" ] || { echo "ac4 RED: the set of REQ identifiers in README.md changed (sha $REQS, expected 01f3611817b98bd95baa2b709ba8c5e9f32be274d337a5fca8541deeb5413794) - t94 rewords prose but adds and removes no requirement marker"; exit 1; }
echo "ac4 GREEN: README.md envelope holds - $CL lines inside 340..400, all-CRLF, pure ASCII, 17 level-2 headings, the REQ identifier set hash unchanged"

ac6.command:
set -u
test -f docs/state/merge_test_index.json || { echo "ac6 RED: docs/state/merge_test_index.json missing"; exit 1; }
command -v python3 >/dev/null || { echo "ac6 RED: python3 missing"; exit 1; }
python3 - <<'PYEOF' || exit 1
import hashlib, json, os, sys
A = "docs/state/outputs/t94_definer_gate_amendment.json"
if not os.path.exists(A):
    sys.stderr.write('ac6 RED: %s missing - t94 ships exactly one amendment record (tests[255]) and no merge candidate is verifiable without it\n' % A)
    raise SystemExit(1)
rec = json.load(open(A, encoding="utf-8"))
if rec.get("card") != "t94":
    sys.stderr.write("ac6 RED: the amendment record does not belong to card t94\n"); raise SystemExit(1)
am = rec.get("amendments", [])
if len(am) != 1:
    sys.stderr.write("ac6 RED: t94 ships exactly one amendment, found %d\n" % len(am)); raise SystemExit(1)
e = am[0]
if e.get("index") != 255:
    sys.stderr.write("ac6 RED: the amendment does not target tests[255]\n"); raise SystemExit(1)
idx = json.load(open("docs/state/merge_test_index.json", encoding="utf-8"))["tests"]
t = idx[str(255)] if isinstance(idx, dict) else idx[255]
cmd = t["command"]
entry_sha = hashlib.sha256(json.dumps(t, separators=(",", ":")).encode("utf-8")).hexdigest()
cmd_sha = hashlib.sha256(cmd.encode("utf-8")).hexdigest()
regions = e.get("replaced_regions", [])
if not regions:
    sys.stderr.write("ac6 RED: the amendment carries no replaced_regions - the edit must be reconstructible\n"); raise SystemExit(1)
def apply_regions(src, pairs, direction):
    out = src
    for r in pairs:
        needle = r["from"] if direction == "forward" else r["to"]
        repl = r["to"] if direction == "forward" else r["from"]
        if out.count(needle) != 1:
            sys.stderr.write("ac6 RED: a replaced_region %s text is not unique in the shipped tests[255] command - the record does not describe the shipped bytes\n" % ("from" if direction == "forward" else "to")); raise SystemExit(1)
        out = out.replace(needle, repl, 1)
    return out
nc = e.get("negative_control_matrix", [])
if len(nc) < 5:
    sys.stderr.write("ac6 RED: the amendment needs at least five negative-control legs, found %d\n" % len(nc)); raise SystemExit(1)
bad = [x.get("case") for x in nc if x.get("measured_rc") != x.get("expected_rc")]
if bad:
    sys.stderr.write("ac6 RED: negative-control legs not as expected: " + ",".join(str(b) for b in bad) + "\n"); raise SystemExit(1)
if cmd_sha == e["old_command_sha256"]:
    if entry_sha != e["entry_sha_before"]:
        sys.stderr.write("ac6 RED: the index still holds the OLD tests[255] command but the entry sha moved - the entry was edited outside the amendment record\n"); raise SystemExit(1)
    fwd = apply_regions(cmd, regions, "forward")
    if hashlib.sha256(fwd.encode("utf-8")).hexdigest() != e["new_command_sha256"]:
        sys.stderr.write("ac6 RED: applying the replaced_regions forward to the shipped OLD command does not reproduce new_command_sha256 - the record does not describe the intended edit\n"); raise SystemExit(1)
    state = "pre-amendment (old command and entry sha both match the record pins; the regions reconstruct the amended command)"
elif cmd_sha == e["new_command_sha256"]:
    if entry_sha != e["entry_sha_after"]:
        sys.stderr.write("ac6 RED: the index holds the AMENDED tests[255] command but not the recorded entry sha - the amended entry drifted from the record\n"); raise SystemExit(1)
    rev = apply_regions(cmd, regions, "reverse")
    if hashlib.sha256(rev.encode("utf-8")).hexdigest() != e["old_command_sha256"]:
        sys.stderr.write("ac6 RED: reversing the replaced_regions out of the shipped AMENDED command does not reproduce old_command_sha256 - the record and the index disagree\n"); raise SystemExit(1)
    if "ac3 GREEN: API OVERVIEW AND RENDER LIVE STATE" not in cmd:
        sys.stderr.write("ac6 RED: the amended command lost its LIVE STATE GREEN message\n"); raise SystemExit(1)
    state = "post-amendment (new command and entry sha both match the record pins; the regions reverse to the old command)"
else:
    sys.stderr.write("ac6 RED: the shipped tests[255] command sha %s matches NEITHER old_command_sha256 nor new_command_sha256 - the index drifted under the amendment\n" % cmd_sha[:16]); raise SystemExit(1)
print("ac6 GREEN: the tests[255] amendment record is present and reconstructs the shipped index bytes in the %s state - replaced_regions reverse to old_command_sha256, the entry sha matches the recorded pin, and all %d negative-control legs are as-expected" % (state, len(nc)))
PYEOF
